import {countryInfo,baseCountries,relationCountries} from './country-actions.js';
import {AREAS} from './world.js';
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function countryActionTarget(s,card,cards){const base=card.effect==='base',ids=(base?baseCountries(s,card):relationCountries(s,card)).filter(id=>!card.targetCountry||id===card.targetCountry);
 return (card.countrySearchRegion?`<p>检索${AREAS[card.countrySearchRegion].name}的全部剩余国家牌；正常支付结盟费用后重洗该地区余牌。</p>`:'')+`<label>${base?'建基地的盟国':'结盟国家'}<select id="basic-country">${ids.map(id=>`<option value="${id}">${esc(cards[id]?.name)} · ${AREAS[countryInfo(id).region].name} · 价值${countryInfo(id).countryValue}</option>`).join('')||'<option value="">暂无合法国家</option>'}</select></label>`+(card.countrySearchRegion?'<div id="basic-country-face"></div>':'')+(base?'<label>从待命区派出的军队<input id="basic-send" type="number" min="1" max="3" value="1" step="1"></label><p class="minor">'+(card.freeBaseDeployment?'建基地5资金；从待命区派出1～3支军队，派兵免费，无视国家价值。':'建基地5资金，每支派出军队另付5资金；至少派1支，最多为国家价值。')+'</p>':(card.relationDiscount?`<label><input id="basic-relation-discount" type="checkbox" checked> 本次改善关系少花费${card.relationDiscount}外交</label>`:'')+'<fieldset id="basic-discounts"><legend>横置当地盟国减费 · 可不选</legend></fieldset>'+(card.moneyDiplomacy?'<label>以资金代替的外交数量<input id="basic-money-diplomacy" type="number" min="0" max="3" value="0" step="1"></label><p class="minor">每点外交可用3资金替代。</p>':''));
}
export function countryActionSummary(preview){return `支付${preview.cost}${preview.effect==='base'?'资金':'外交'}${preview.moneyCost?'、'+preview.moneyCost+'资金':''}；${preview.effect==='base'?'建立基地并派出'+preview.send+'军队':preview.previous?'升级起始盟国，保留原有投资、基地和贸易符号':'获得新盟国'}。${preview.influence?'在'+AREAS[preview.region].name+'放置影响力，获得'+preview.vp+'分。':'本次不放置影响力。'}${preview.countrySearchRegion?'随后重洗该地区剩余国家牌，并揭示顶牌。':''}`;}
